mod solution;

fn main() {
    let cases = [
    (r#"[2,4,6,8,10]"#, r#"4,6,8"#),
    (r#"[1,2,3,4]"#, r#"2,3"#),
    (r#"
[1,2,3,4]
"#, r#"2,3"#),
    (r#"  
[2,4,6,8,10]
  "#, r#"4,6,8"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS rolling-window-statistic");
}
